      "ই-কমার্স ও ড্রপশিপিং: কোনো গোপন রহস্য নয়, আধুনিক বাণিজ্যের রূপ",
      "কেন এই বইটি লেখা এবং কাদের জন্য সবচেয়ে বেশি কার্যকর"
