    "title": "এবার শুরু করার পালা",
    "content": "বরং সেই revenue যে স্বাধীনতা কিনে দিতে পারে, সেটিকেও সাফল্যের অংশ হিসেবে দেখে।\nনিজের পছন্দের project বেছে নেওয়ার স্বাধীনতা।\nপ্রিয় মানুষদের সাহায্য করার স্বাধীনতা।\nএবং পৃথিবীর যেকোনো জায়গায় বসে কাজ করার স্বাধীনতা—যেখানে একটি internet signal পৌঁছায়।\n\n---\n\n## এবার শুরু করার পালা\n\nআমি আপনাকে অনুরোধ করছি, বইয়ের পৃষ্ঠা উল্টাতে থাকুন—কিন্তু একজন passive reader হিসেবে নয়।\nএকজন active participant হিসেবে।\n\nMargin-এ নিজের notes লিখুন।\nনিজের অভিজ্ঞতা যেখানে আমার কথার সঙ্গে মিলবে না, সেখানে আমার সঙ্গে দ্বিমত করুন।\nআর সবচেয়ে গুরুত্বপূর্ণ—\nসবকিছু পরীক্ষা করুন।\n\nMarketplace মতামতের জন্য টাকা দেয় না।\nMarketplace proof-এর জন্য টাকা দেয়।\nChapter Ten-এ পৌঁছানোর সময় আপনি নিজের সেই proof তৈরি করে ফেলবেন।\nএকটি একটি করে experiment।\nএকটি একটি করে lesson।\nএকটি একটি করে customer।\nআর শেষ পর্যন্ত—\nসাতটি ক্লিক করে করে।\n\nচলুন, শুরু করি।",
