    "title": "১. সিল্ক রোড (খ্রিস্টপূর্ব ২য় শতাব্দী – খ্রিস্টীয় ১৫শ শতাব্দী)",
    "content": "### ১. সিল্ক রোড (খ্রিস্টপূর্ব ২য় শতাব্দী – খ্রিস্টীয় ১৫শ শতাব্দী)\n- এটি ছিল প্রাচীন বিশ্বের অন্যতম বৃহৎ “cross-border trade” network।\n- ব্যবসায়ীরা আজকের dashboard বা PayPal-এর পরিবর্তে উট, কাফেলা এবং মুদ্রার থলি ব্যবহার করতেন।\n- একটি যাত্রা সম্পন্ন করতে কয়েক মাস সময় লেগে যেতে পারত।\n- ডাকাত, খারাপ আবহাওয়া এবং রাজনৈতিক অস্থিরতার ঝুঁকি ছিল নিয়মিত ঘটনা।\n\n### ২. Mail-Order Catalog (১৮০০-এর দশকের মাঝামাঝি)\n- Montgomery Ward এবং পরবর্তীতে Sears printed catalog-কে এমন এক shopping system-এ পরিণত করেছিল, যাকে বলা যায় “কাগজের Amazon।”\n- গ্রামের পরিবারগুলো ডাকযোগে লাঙল, পোশাক এবং এমনকি পুরো kit house-ও অর্ডার করতে পারত।\n- Check বা money order-এর মাধ্যমে payment সম্পন্ন হতে কয়েক সপ্তাহ সময় লাগত।\n- পণ্যগুলো rail network-এর মাধ্যমে ক্রেতার কাছে পৌঁছাত।\n\n### ৩. TeleShopping ও TV Infomercials (১৯৭০–১৯৮০-এর দশক)\n- Home Shopping Network (HSN) এবং QVC-এর মাধ্যমে মানুষ রাত ২টাতেও ফোন করে গয়না অর্ডার করতে পারত।\n- প্রথমবারের মতো nationwide audience-এর বসার ঘরে সরাসরি sales pitch পৌঁছে গেল।\n\n> **মূল শিক্ষা:** ক্রেতা ও বিক্রেতার মধ্যকার friction যতবার কোনো প্রযুক্তিগত অগ্রগতি কমিয়েছে—রাস্তা, ডাকব্যবস্থা, টেলিফোন—ততবার বাজারের আকার বেড়েছে। ইন্টারনেট শুধু সেই একই পরিবর্তনকে অসাধারণ দ্রুত করে দিয়েছে।",
