    "content": "৩. **Hype শেষ হয়ে গেলেও trust এবং brand equity টিকে থাকে।**\n\n---\n\n## ৪. Marketplace-এর উত্থান\n\n### ১. eBay — ১৯৯৫\n- eBay শুরু হয়েছিল “AuctionWeb” নামে।\n- প্রথম দিকের একটি বিখ্যাত পণ্য ছিল একটি নষ্ট laser pointer।\n- এরপর eBay peer-to-peer rating system চালু করে, যা online transaction-এর ক্ষেত্রে digital trust তৈরিতে গুরুত্বপূর্ণ ভূমিকা রাখে।\n\n### ২. Amazon — ১৯৯৫\n- Amazon বই দিয়ে শুরু করেছিল।\n- বই ছিল একটি low-risk entry point, কারণ physical bookstore-এর তুলনায় Amazon বিশাল long-tail inventory offer করতে পারত।\n- Amazon-এর “Customers First” mindset পরবর্তীতে 1-Click ordering এবং Prime-এর মতো innovation-এর পথ তৈরি করে।\n\n### ৩. Alibaba & Taobao — ১৯৯৯–২০০৩\n- Alibaba ও Taobao চীনের export-import gap-এর একটি বড় অংশ সমাধান করে।",
