    "content": "---\n\n## ৬. COVID-19: Global E-Commerce Adoption-এর Catalyst\n২০২০ সালে যখন lockdown শুরু হলো, তখন e-commerce adoption-এর প্রায় ১০ বছরের বৃদ্ধি মাত্র কয়েক মাসের মধ্যে ঘটে গেল।\nযেসব consumer এবং retailer আগে physical store ছাড়া ব্যবসা বা কেনাকাটা কল্পনাই করতে পারত না, তারাও বাধ্য হয়ে online-এ চলে গেল।\n\n### কিছু উল্লেখযোগ্য তথ্য:\n- যুক্তরাষ্ট্রে ২০২০ সালের Q2-তে e-commerce penetration প্রায় ১৬% থেকে ২৭%-এ উঠে যায়।\n- বাংলাদেশে online grocery sector-এ year-on-year growth প্রায় ৭০% দেখা যায়।\n- চীনে video-based live shopping ব্যাপকভাবে জনপ্রিয় হয় এবং ২০২০ সালে প্রায় $171 billion sales তৈরি করে।\n\nআপনার মতো উদ্যোক্তাদের জন্য এর সবচেয়ে বড় প্রভাব হলো:\n**Pandemic মানুষের online shopping-এর প্রতি comfort level স্থায়ীভাবে বাড়িয়ে দিয়েছে।**\n\n---\n\n## ৭. ই-কমার্স কীভাবে পৃথিবীকে ছোট করে ফেলেছে",
