    "content": "---\n\n## ৫. আপনার “Opportunity Radar” তৈরি করা\n- **Macro Trends:** Remote work, Sustainability, Aging population\n- **Micro Trends:** Mushroom coffee, Desk treadmill, TikTok viral gadgets\n- **Market Inefficiency Checklist:** ডিস্ট্রিবিউশন কি দুর্বল? প্রাইসিং কি অস্বচ্ছ? ইনফরমেশন গ্যাপ কি বেশি?\n- **Blue Ocean Strategy:** Generic রেড ওশানে না গিয়ে এমন স্পেস তৈরি করুন যেখানে প্রতিযোগিতা কম।\n\n---\n\n## ৬. Opportunity বাড়ানোর Psychological Triggers\n- **Scarcity & Urgency:** Limited-edition অফার ও কাউন্টডাউন টাইমার।",
