    "title": "Framework 1: “Problem-Solution” Matrix",
    "content": "### Framework 1: “Problem-Solution” Matrix\nদৈনন্দিন ফ্রাস্ট্রেশন তালিকা তৈরি করে এক্সিস্টিং সলিউশনের দুর্বলতা খুঁজে বের করা (যেমন: পুরনো তোয়ালের বদলে Silicone Paw-Cleaning Cup—যা মাত্র কয়েক সেকেন্ডে কুকুরের কাদাভরা পা পরিষ্কার করে দেয়)।\n\n### Framework 2: “3 Ts” দিয়ে Trend Surfing\n- **Traffic:** কতজন মানুষ খুঁজছে?\n- **Trajectory:** ট্রাফিক বাড়ছে না কমছে?\n- **Time Horizon:** সিজনাল ট্রেন্ড নাকি দীর্ঘমেয়াদি পরিবর্তন?\n\n### Framework 3: “Better Mouse-Trap” Blueprint\nবেস্ট সেলার প্রোডাক্টের ১–৩ স্টার রিভিউ পড়ে কাস্টমার কমপ্লেইনগুলো (যেমন: জিপার ভেঙে যায়, ব্যাটারি দ্রুত শেষ হয়) সমাধান করে আপগ্রেডেড ভার্সন আনা।\n\n### Framework 4: Data Triangle",
